 24	import java.util.Map;
 25	import java.util.Map.Entry;
 26	import java.util.SortedSet;
 27	import java.util.TreeSet;
 28	
 29	/**
 30	 * Formats {@link InitializrServiceMetadata} into a human-readable capabilities report.
 31	 *
 32	 * @author Stephane Nicoll
 33	 * @author Andy Wilkinson
 34	 */
 35	class ServiceCapabilitiesReportFormatter {
 36	
 37		private static final String NEW_LINE = System.lineSeparator();
 38	
 39		String format(String url, InitializrServiceMetadata metadata) {
 40			String header = "Capabilities of " + url;
 41			StringBuilder report = new StringBuilder();
 42			report.append("=".repeat(header.length())).append(NEW_LINE);
 43			report.append(header).append(NEW_LINE);
 44			report.append("=".repeat(header.length())).append(NEW_LINE);
 45			report.append(NEW_LINE);
 46			reportAvailableDependencies(metadata, report);
 47			report.append(NEW_LINE);
 48			reportAvailableProjectTypes(metadata, report);
 49			report.append(NEW_LINE);
 50			reportDefaults(report, metadata);
 51			return report.toString();
 52		}
 53	
 54		private void reportAvailableDependencies(InitializrServiceMetadata metadata, StringBuilder report) {
 55			report.append("Available dependencies:").append(NEW_LINE);
 56			report.append("-----------------------").append(NEW_LINE);
 57			List<Dependency> dependencies = getSortedDependencies(metadata);
 58			for (Dependency dependency : dependencies) {
 59				report.append(dependency.getId()).append(" - ").append(dependency.getName());
 60				if (dependency.getDescription() != null) {
 61					report.append(": ").append(dependency.getDescription());
 62				}
 63				report.append(NEW_LINE);
 64			}
 65		}
 66	
 67		private List<Dependency> getSortedDependencies(InitializrServiceMetadata metadata) {
 68			List<Dependency> dependencies = new ArrayList<>(metadata.getDependencies());
 69			dependencies.sort(Comparator.comparing(Dependency::getId));
 70			return dependencies;
 71		}
 72	
 73		private void reportAvailableProjectTypes(InitializrServiceMetadata metadata, StringBuilder report) {
 74			report.append("Available project types:").append(NEW_LINE);
 75			report.append("------------------------").append(NEW_LINE);
 76			SortedSet<Entry<String, ProjectType>> entries = new TreeSet<>(Entry.comparingByKey());
 77			entries.addAll(metadata.getProjectTypes().entrySet());
 78			for (Entry<String, ProjectType> entry : entries) {
 79				ProjectType type = entry.getValue();
 80				report.append(entry.getKey()).append(" -  ").append(type.getName());
 81				if (!type.getTags().isEmpty()) {
 82					reportTags(report, type);
 83				}
 84				if (type.isDefaultType()) {
 85					report.append(" (default)");
 86				}
 87				report.append(NEW_LINE);
 88			}
 89		}
 90	
 91		private void reportTags(StringBuilder report, ProjectType type) {
 92			Map<String, String> tags = type.getTags();
 93			Iterator<Map.Entry<String, String>> iterator = tags.entrySet().iterator();
 94			report.append(" [");
 95			while (iterator.hasNext()) {
 96				Map.Entry<String, String> entry = iterator.next();
 97				report.append(entry.getKey()).append(":").append(entry.getValue());
 98				if (iterator.hasNext()) {
 99					report.append(", ");
100				}
101			}
102			report.append("]");
103		}
104	
105		private void reportDefaults(StringBuilder report, InitializrServiceMetadata metadata) {
106			report.append("Defaults:").append(NEW_LINE);
107			report.append("---------").append(NEW_LINE);
108			List<String> defaultsKeys = new ArrayList<>(metadata.getDefaults().keySet());
109			Collections.sort(defaultsKeys);
110			for (String defaultsKey : defaultsKeys) {
111				String defaultsValue = metadata.getDefaults().get(defaultsKey);
112				report.append(defaultsKey).append(": ").append(defaultsValue).append(NEW_LINE);
113			}
114		}
